package state

import (
	"container/list"
	"sync"
	"time"
)

type rateLimiter struct {
	mu        sync.Mutex
	rps       float64
	burst     float64
	tokens    float64
	last      time.Time
	queue     *list.List
	queueMax  int
	timeout   time.Duration
	rateLimited uint64
	queued     uint64
	timeouts   uint64
}

func newRateLimiter(rps, burst int, queueDepth int, timeoutMs int) *rateLimiter {
	return &rateLimiter{
		rps:      float64(rps),
		burst:    float64(burst),
		tokens:   float64(burst),
		last:     time.Now(),
		queue:    list.New(),
		queueMax: queueDepth,
		timeout:  time.Duration(timeoutMs) * time.Millisecond,
	}
}

func (rl *rateLimiter) update(rps, burst int, queueDepth int, timeoutMs int) {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.rps = float64(rps)
	rl.burst = float64(burst)
	if rl.tokens > rl.burst {
		rl.tokens = rl.burst
	}
	rl.queueMax = queueDepth
	rl.timeout = time.Duration(timeoutMs) * time.Millisecond
}

func (rl *rateLimiter) refillLocked(now time.Time) {
	elapsed := now.Sub(rl.last).Seconds()
	if elapsed > 0 {
		rl.tokens += rl.rps * elapsed
		if rl.burst > 0 && rl.tokens > rl.burst {
			rl.tokens = rl.burst
		}
		rl.last = now
	}
}

func (rl *rateLimiter) tryAcquire(now time.Time) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.refillLocked(now)
	if rl.rps <= 0 || rl.tokens >= 1 {
		if rl.rps > 0 {
			rl.tokens -= 1
		}
		return true
	}
	return false
}

type queuedWaiter struct {
	deadline time.Time
	ch       chan struct{}
}

func (rl *rateLimiter) acquire(now time.Time) (bool, bool) {
	rl.mu.Lock()
	if rl.rps <= 0 {
		rl.mu.Unlock()
		return true, false
	}
	rl.refillLocked(now)
	if rl.tokens >= 1 {
		rl.tokens -= 1
		rl.mu.Unlock()
		return true, false
	}
	if rl.queueMax <= 0 {
		rl.rateLimited++
		rl.mu.Unlock()
		return false, false
	}
	if rl.queue.Len() >= rl.queueMax {
		rl.rateLimited++
		rl.mu.Unlock()
		return false, false
	}
	deadline := now.Add(rl.timeout)
	waiter := &queuedWaiter{deadline: deadline, ch: make(chan struct{})}
	elem := rl.queue.PushBack(waiter)
	rl.queued++
	rl.mu.Unlock()

	timer := time.NewTimer(rl.timeout)
	defer timer.Stop()
	select {
	case <-waiter.ch:
		return true, true
	case <-timer.C:
		rl.mu.Lock()
		select {
		case <-waiter.ch:
			rl.mu.Unlock()
			return true, true
		default:
		}
		if elem.Value != nil {
			rl.queue.Remove(elem)
		}
		rl.timeouts++
		rl.mu.Unlock()
		return false, true
	}
}

func (rl *rateLimiter) releaseToken() {
	rl.mu.Lock()
	if rl.queue.Len() > 0 {
		elem := rl.queue.Front()
		waiter := elem.Value.(*queuedWaiter)
		rl.queue.Remove(elem)
		rl.mu.Unlock()
		close(waiter.ch)
		return
	}
	rl.mu.Unlock()
}

func (rl *rateLimiter) status() (tokens float64, queueDepth int, rateLimited uint64, queued uint64, timeouts uint64, rps float64, burst float64) {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.refillLocked(time.Now())
	return rl.tokens, rl.queue.Len(), rl.rateLimited, rl.queued, rl.timeouts, rl.rps, rl.burst
}
