func (ss *ServiceState) AcquireRateLimitToken() (bool, bool) {
	ss.mu.Lock()
	rl := ss.rateLimiter
	ss.mu.Unlock()
	if rl == nil {
		return true, false
	}
	return rl.acquire(time.Now())
}

func (ss *ServiceState) ReleaseRateLimitToken() {
	ss.mu.Lock()
	rl := ss.rateLimiter
	ss.mu.Unlock()
	if rl != nil {
		rl.releaseToken()
	}
}

func (ss *ServiceState) RateLimitStatus() (tokens float64, queueDepth int, rateLimited uint64, queued uint64, timeouts uint64, rps float64, burst float64) {
	ss.mu.Lock()
	rl := ss.rateLimiter
	ss.mu.Unlock()
	if rl == nil {
		return 0, 0, 0, 0, 0, 0, 0
	}
	return rl.status()
}

func (ss *ServiceState) RetryConfig() (maxRetries int, delayMs int, multiplier float64, maxDelayMs int) {
	ss.mu.Lock()
	defer ss.mu.Unlock()
	return ss.MaxRetries, ss.RetryDelayMs, ss.RetryBackoffMultiplier, ss.RetryMaxDelayMs
}

func (s *State) SetRateLimit(name string, rps, burst int) error {
	ss := s.GetService(name)
	if ss == nil {
		return errNotFound("service not found")
	}
	ss.mu.Lock()
	defer ss.mu.Unlock()
	ss.RateLimitRps = rps
	ss.RateLimitBurst = burst
	if ss.rateLimiter == nil {
		ss.rateLimiter = newRateLimiter(rps, burst, ss.RateLimitQueueDepth, ss.RateLimitQueueTimeoutMs)
	} else {
		ss.rateLimiter.update(rps, burst, ss.RateLimitQueueDepth, ss.RateLimitQueueTimeoutMs)
	}
	return nil
}

func (s *State) RateLimitStatus(name string) (tokens float64, queueDepth int, rateLimited uint64, queued uint64, timeouts uint64, rps float64, burst float64, ok bool) {
	ss := s.GetService(name)
	if ss == nil {
		return 0, 0, 0, 0, 0, 0, 0, false
	}
	tokens, queueDepth, rateLimited, queued, timeouts, rps, burst = ss.RateLimitStatus()
	return tokens, queueDepth, rateLimited, queued, timeouts, rps, burst, true
}
