type rateLimiter struct {
	mu         sync.Mutex
	rps        float64
	burst      float64
	tokens     float64
	last       time.Time
	queueMax   int
	timeout    time.Duration
	rateLimited uint64
	queued     uint64
	timeouts   uint64
	queueDepth int
}

func newRateLimiter(rps, burst int, queueDepth int, timeoutMs int) *rateLimiter {
	return &rateLimiter{
		rps:       float64(rps),
		burst:     float64(burst),
		tokens:    float64(burst),
		last:      time.Now(),
		queueMax:  queueDepth,
		timeout:   time.Duration(timeoutMs) * time.Millisecond,
	}
}

func (rl *rateLimiter) update(rps, burst int, queueDepth int, timeoutMs int) {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.rps = float64(rps)
	rl.burst = float64(burst)
	if rl.tokens > rl.burst {
		rl.tokens = rl.burst
	}
	rl.queueMax = queueDepth
	rl.timeout = time.Duration(timeoutMs) * time.Millisecond
}

func (rl *rateLimiter) refillLocked(now time.Time) {
	elapsed := now.Sub(rl.last).Seconds()
	if elapsed > 0 {
		rl.tokens += rl.rps * elapsed
		if rl.burst > 0 && rl.tokens > rl.burst {
			rl.tokens = rl.burst
		}
		rl.last = now
	}
}

func (rl *rateLimiter) tryAcquireLocked(now time.Time) bool {
	if rl.rps <= 0 {
		return true
	}
	rl.refillLocked(now)
	if rl.tokens >= 1 {
		rl.tokens -= 1
		return true
	}
